A;EACA,kBAAA;EACA,YAAA;EACA,0BAAA;EACA,YAAA;AACA;AAEA;EACA,oBAAA;EACA,mBAAA;EACA,QAAA;EACA,YAAA;EACA,eAAA;EACA,0BAAA;AACA;AAEA;EACA,WAAA;EACA,YAAA;AACA;AAEA;EACA,kBAAA;AACA;AAEA;EACA,kBAAA;EACA,QAAA;EACA,SAAA;EACA,eAAA;EACA,WAAA;EACA,YAAA;EACA,aAAA;EACA,aAAA;EACA,QAAA;EACA,0CAAA;AACA;AAEA;EACA,aAAA;EACA,mBAAA;EACA,QAAA;EACA,0BAAA;EACA,eAAA;AACA;AAEA;EACA,UAAA;EACA,gBAAA;AACA;AAEA;EACA,aAAA;EACA,mBAAA;EACA,8BAAA;EACA,2BAAA;EACA,yCAAA;AACA;AAEA;EACA,0BAAA;EACA,gBAAA;EACA,uBAAA;AACA;AAEA;EACA,gBAAA;AACA;AAEA;EACA,WAAA;EACA,yBAAA;EACA,gBAAA;EACA,0BAAA;AACA;AAEA;EACA,kBAAA;EACA,oCAAA;EACA,+BAAA;EACA,0BAAA;EACA,gBAAA;EACA,mBAAA;EACA,yCAAA;EACA,iBAAA;AACA;AAEA;EACA,eAAA;AACA;AAEA;EACA,qBAAA;AACA;AAEA;EACA,gBAAA;EACA,eAAA;AACA;AAEA;EACA,kBAAA;EACA,yCAAA;EACA,qBAAA;EACA,mBAAA;EACA,sBAAA;AACA;AAEA;EACA,eAAA;EACA,2CAAA;AACA;AAEA;EACA,oCAAA;AACA;AAEA;EACA,gBAAA;EACA,qBAAA;AACA;AAEA;EACA,qBAAA;EACA,gBAAA;EACA,oCAAA;EACA,mBAAA;EACA,cAAA;EACA,gBAAA;EACA,0BAAA;AACA;AAEA;EACA,mBAAA;EACA,cAAA;AACA;AAEA;EACA,cAAA;EACA,gBAAA;AACA;AAEA;EACA,aAAA;EACA,QAAA;AACA;AAEA;EACA,eAAA;EACA,cAAA;EACA,gBAAA;AACA;AAEA;EACA,oBAAA;EACA,mBAAA;EACA,QAAA;EACA,gBAAA;EACA,kCAAA;EACA,oCAAA;EACA,6BAAA;EACA,qBAAA;EACA,0BAAA;EACA,gBAAA;EACA,eAAA;AACA;AAEA;EACA,oCAAA;EACA,8BAAA;AACA;AAEA;EACA,WAAA;EACA,YAAA;EACA,uBAAA;AACA;AAEA;EACA,WAAA;EACA,YAAA;EACA,2BAAA;AACA;AAEA;EACA,WAAA;EACA,YAAA;EACA,2BAAA;AACA;AAEA;EACA,uBAAA;AACA;AAEA;EACA,kBAAA;EACA,kBAAA;EACA,+BAAA;AACA;AAEA;EACA,aAAA;EACA,mBAAA;EACA,8BAAA;EACA,eAAA;EACA,kBAAA;EACA,2BAAA;EACA,sCAAA;EACA,6BAAA;AACA;AAEA;EACA,0BAAA;EACA,+BAAA;AACA;AAEA;EACA,aAAA;EACA,mBAAA;EACA,QAAA;EACA,iBAAA;AACA;AAEA;EACA,eAAA;EACA,YAAA;EACA,cAAA;EACA,kCAAA;EACA,+BAAA;EACA,6BAAA;EACA,+BAAA;EACA,0BAAA;EACA,gBAAA;EACA,eAAA;AACA;AAEA;EACA,oCAAA;EACA,qBAAA;AACA;AAEA;EACA,YAAA;EACA,mBAAA;AACA;AAEA;EACA,4BAAA;EACA,4BAAA;EACA,8BAAA;AACA;AAEA;EACA,gBAAA;EACA,0BAAA;EACA,+BAAA;AACA;AAEA;EACA,aAAA;EACA,8BAAA;EACA,mBAAA;EACA,eAAA;EACA,wBAAA;EACA,gBAAA;EACA,0BAAA;EACA,2BAAA;AACA;AAEA;EACA,qBAAA;AACA;AAEA;EACA,0BAAA;EACA,2BAAA;EACA,mBAAA;AACA;AAEA;EACA,sCAAA;EACA,0BAAA;EACA,gBAAA;AACA;;AAEA;;;;8EAIA;AACA;EACA,aAAA;EACA,mBAAA;EACA,eAAA;EACA,wBAAA;EACA,2BAAA;AACA;AACA;EACA,aAAA;EACA,mBAAA;EACA,wBAAA;EACA,YAAA;AACA;AACA;EACA,aAAA;EACA,gBAAA;EACA,kCAAA;EACA,+BAAA;EACA,6BAAA;AACA;AACA;EACA,iBAAA;EACA,0BAAA;AACA;AACA;EACA,aAAA;EACA,iBAAA;EACA,SAAA;EACA,wCAAA;EACA,gBAAA;EACA,uBAAA;EACA,+BAAA;EACA,0BAAA;EACA,gBAAA;EACA,mBAAA;EACA,eAAA;AACA;AACA,wEAAA,eAAA;AAAA;AACA;EACA,4BAAA;EACA,4BAAA;AACA;AACA;EACA,aAAA;EACA,mBAAA;EACA,uBAAA;EACA,gBAAA;AACA;AACA;EACA,WAAA;EACA,YAAA;AACA;AACA;EACA,mCAAA;EACA,oBAAA;AACA;AACA;EACA,aAAA;EACA,mBAAA;EACA,gBAAA;EACA,kCAAA;EACA,+BAAA;EACA,6BAAA;AACA;AACA;EACA,aAAA;EACA,mBAAA;EACA,QAAA;EACA,iBAAA;EACA,SAAA;EACA,wCAAA;EACA,uBAAA;EACA,qBAAA;EACA,0BAAA;EACA,gBAAA;EACA,mBAAA;EACA,oBAAA;AACA;AACA;EACA,WAAA;EACA,YAAA;EACA,uBAAA;AACA;AACA;EACA,eAAA;EACA,mDAAA;EACA,kBAAA;AACA;AACA;EACA,wDAAA;EACA,uBAAA;AACA;AACA;EACA,mCAAA;EACA,oBAAA;AACA;AACA;EACA,kBAAA;EACA,QAAA;EACA,SAAA;EACA,UAAA;EACA,oBAAA;EACA,SAAA;EACA,UAAA;EACA,SAAA;AACA;AACA;EACA,aAAA;EACA,mBAAA;EACA,wBAAA;EACA,iBAAA;EACA,2BAAA;EACA,uCAAA;EACA,qBAAA;AACA;AACA;EACA,WAAA;EACA,YAAA;EACA,cAAA;EACA,uBAAA;AACA;AACA;EACA,aAAA;EACA,oDAAA;EACA,wBAAA;EACA,gBAAA;AACA;AACA;EACA,aAAA;EACA,wBAAA;EACA,gBAAA;AACA;AACA;EACA,aAAA;EACA,mBAAA;EACA,uBAAA;EACA,wBAAA;EACA,iBAAA;AACA;;AAEA,2DAAA;AACA;EACA,mCAAA;EACA,oBAAA;AACA;AACA;EACA,mCAAA;EACA,oBAAA;EACA,oCAAA;AACA;AACA;;;EAGA,mCAAA;EACA,mBAAA;AACA;AAEA;EACA,kBAAA;EACA,UAAA;EACA,WAAA;EACA,UAAA;EACA,YAAA;EACA,gBAAA;EACA,sBAAA;EACA,mBAAA;EACA,SAAA;AACA;AAEA;AACA;IACA,WAAA;IACA,cAAA;IACA,gCAAA;IACA,cAAA;IACA,sCAAA;AACA;AACA;AAEA;AACA;IACA,sBAAA;IACA,uBAAA;AACA;AACA;IACA,WAAA;IACA,cAAA;IACA,eAAA;AACA;AACA;IACA,WAAA;AACA;AACA;AAEA;AACA;IACA,WAAA;IACA,8BAAA;AACA;AACA;IACA,cAAA;IACA,uBAAA;IACA,0BAAA;AACA;AACA;IACA,WAAA;IACA,gBAAA;AACA;AACA;IACA,cAAA;IACA,kBAAA;AACA;AACA","sourcesContent":["<template>\n  <div class=\"portfolio-table-view\">\n    <!-- ── Top Header & Timestamp ── -->\n    <header class=\"portfolio-table-view__header\">\n      <div class=\"portfolio-table-view__titles\">\n        <h3 class=\"portfolio-table-view__title\">{{ t('Planning Overview – Initiation Phase') }}</h3>\n        <p class=\"portfolio-table-view__subtitle\">{{ t('Drill-down view from approved Portfolio view') }}</p>\n      </div>\n      <div class=\"portfolio-table-view__meta\">\n        <span>{{ t('Last updated {time}', { time: lastUpdatedText }) }}</span>\n        <button\n          type=\"button\"\n          class=\"iz-btn iz-btn--quiet iz-btn--sm\"\n          :title=\"t('Refresh')\"\n          :disabled=\"loading\"\n          @click=\"fetchTableData\"\n        >\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" class=\"portfolio-table-view__refresh-icon\" :class=\"{ 'portfolio-table-view__refresh-icon--spinning': loading }\">\n            <polyline points=\"23 4 23 10 17 10\" />\n            <path d=\"M20.49 15a9 9 0 1 1-2.12-9.36L23 10\" />\n          </svg>\n        </button>\n      </div>\n    </header>\n\n    <!-- ── Top Controls Toolbar ── -->\n    <div class=\"portfolio__toolbar iz-card iz-card--flat\" :aria-label=\"t('Planning overview filters')\">\n      <div class=\"portfolio__segmented\" role=\"group\" :aria-label=\"t('Portfolio scope')\">\n        <button\n          type=\"button\"\n          class=\"portfolio__segment\"\n          :class=\"{ 'portfolio__segment--active': scope === 'mine' }\"\n          :aria-pressed=\"String(scope === 'mine')\"\n          @click=\"$emit('change-scope', { scope: 'mine', teamId: teamId })\"\n        >\n          {{ t('My projects') }}\n        </button>\n        <button\n          v-if=\"teams.length\"\n          type=\"button\"\n          class=\"portfolio__segment\"\n          :class=\"{ 'portfolio__segment--active': scope === 'team' }\"\n          :aria-pressed=\"String(scope === 'team')\"\n          @click=\"$emit('change-scope', { scope: 'team', teamId: teamId || teams[0].id })\"\n        >\n          {{ t('My team') }}\n        </button>\n      </div>\n\n      <div class=\"portfolio__period-stepper\" :title=\"t('Period controls the weekly workload strip below; click the date to jump to a specific week')\">\n        <button type=\"button\" class=\"portfolio__segment portfolio__segment--icon\" :aria-label=\"t('Previous 6 weeks')\" :title=\"t('Previous 6 weeks')\" @click=\"movePeriod(-42)\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n            <polyline points=\"15 18 9 12 15 6\" />\n          </svg>\n        </button>\n        <button\n          type=\"button\"\n          class=\"portfolio__period-display portfolio__period-display--clickable\"\n          :title=\"t('Click to jump to a specific date')\"\n          :aria-label=\"t('Current period: {period}. Click to pick a specific date.', { period: periodLabel })\"\n          @click=\"openDatePicker\"\n        >\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" aria-hidden=\"true\">\n            <rect x=\"3\" y=\"4\" width=\"18\" height=\"17\" rx=\"2\" />\n            <path d=\"M8 2v4M16 2v4M3 9h18\" />\n          </svg>\n          <span>{{ periodLabel }}</span>\n          <input\n            ref=\"tableDatePicker\"\n            type=\"date\"\n            class=\"portfolio__date-input-hidden\"\n            :value=\"currentWeekStart\"\n            aria-hidden=\"true\"\n            tabindex=\"-1\"\n            @change=\"onDatePicked\"\n            @click.stop\n          />\n        </button>\n        <button type=\"button\" class=\"portfolio__segment portfolio__segment--icon\" :aria-label=\"t('Next 6 weeks')\" :title=\"t('Next 6 weeks')\" @click=\"movePeriod(42)\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n            <polyline points=\"9 18 15 12 9 6\" />\n          </svg>\n        </button>\n        <button type=\"button\" class=\"portfolio__segment\" :title=\"t('Reset to current 6 weeks')\" @click=\"resetPeriod\">{{ t('Current') }}</button>\n      </div>\n\n      <div class=\"portfolio__capacity\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\" /><circle cx=\"9\" cy=\"7\" r=\"4\" /><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\" /><path d=\"M16 3.13a4 4 0 0 1 0 7.75\" /></svg>\n        <div class=\"portfolio-table-view__capacity-box\">\n          <select\n            v-if=\"scope === 'team' && teams.length > 1\"\n            class=\"iz-select\"\n            :aria-label=\"t('Team')\"\n            :value=\"teamId\"\n            @change=\"$emit('change-scope', { scope: 'team', teamId: Number($event.target.value) })\"\n          >\n            <option v-for=\"team in teams\" :key=\"team.id\" :value=\"team.id\">{{ team.name }}</option>\n          </select>\n          <small v-if=\"teamSummaryText\">{{ teamSummaryText }}</small>\n        </div>\n      </div>\n    </div>\n\n    <!-- ── Section 1: Weekly Work Preparation Load Strip ── -->\n    <section class=\"iz-card portfolio-table-view__workload\">\n      <header class=\"iz-panel__header portfolio__workload-header\">\n        <h4 class=\"iz-panel__title\">{{ t('Weekly work preparation load') }}</h4>\n        <span class=\"portfolio-table-view__workload-note\">{{ t('Same period as Portfolio: {range}', { range: periodWeekRange }) }}</span>\n      </header>\n\n      <div v-if=\"loading\" class=\"portfolio__status-state iz-empty\">{{ t('Loading workload...') }}</div>\n      <div v-else-if=\"error\" class=\"portfolio__status-state iz-error\">{{ error }}</div>\n      <div v-else-if=\"!weeks.length\" class=\"portfolio__status-state iz-empty\">{{ t('No capacity data available.') }}</div>\n      <div v-else class=\"portfolio__weeks\">\n        <article v-for=\"week in weeks\" :key=\"week.label\" class=\"iz-card iz-card--flat portfolio-week portfolio-table-view__week-card\">\n          <header class=\"portfolio-table-view__week-header\">\n            <strong>{{ weekDisplayLabel(week) }}</strong>\n            <small>{{ formatWeekRange(week.start, week.end) }}</small>\n          </header>\n          <div class=\"portfolio-table-view__week-sub\">\n            <span>{{ t('Starting {n}', { n: week.starting }) }}</span>\n            <span class=\"portfolio-table-view__dot\">·</span>\n            <span>{{ t('Ongoing {n}', { n: week.continuing }) }}</span>\n            <span class=\"portfolio-table-view__dot\">·</span>\n            <span>{{ t('Ending {n}', { n: week.ending }) }}</span>\n          </div>\n          <div class=\"portfolio-table-view__week-badge\" :class=\"workloadBadgeClass(week)\">\n            <strong>{{ n('%n project', '%n projects', week.totalActive) }}</strong>\n            <span>{{ workloadStatusText(week) }}</span>\n          </div>\n        </article>\n      </div>\n      <PeopleLoadGrid\n        v-if=\"tableData && !loading && !error\"\n        :people=\"tableData.people || []\"\n        :weeks=\"weeks\"\n        :projects=\"tableData.capacityProjects || []\"\n        :overload-warnings=\"tableData.overloadWarnings || []\"\n        :max-per-person=\"maxPerPerson\"\n        :show-teams=\"false\"\n      />\n    </section>\n\n\n    <!-- ── Filter Chips Bar & Search/Export/Columns ── -->\n    <div class=\"portfolio-table-view__filters-row\">\n      <div class=\"portfolio-table-view__chips\" role=\"group\" :aria-label=\"t('Progression filters')\">\n        <button\n          v-for=\"chip in filterChips\"\n          :key=\"chip.key\"\n          type=\"button\"\n          class=\"portfolio-table-view__chip\"\n          :class=\"{\n            'portfolio-table-view__chip--active': activeFilter === chip.key,\n            'portfolio-table-view__chip--danger': chip.key === 'gaps' && chip.count > 0,\n            'portfolio-table-view__chip--success': chip.key === '100',\n            'portfolio-table-view__chip--warning': chip.key === '75-99',\n            'portfolio-table-view__chip--period': chip.key === 'in-period'\n          }\"\n          :aria-pressed=\"String(activeFilter === chip.key)\"\n          @click=\"activeFilter = chip.key\"\n        >\n          <span>{{ chip.label }}</span>\n          <span class=\"portfolio-table-view__chip-count\">{{ t('· {n}', { n: chip.count }) }}</span>\n        </button>\n      </div>\n\n      <div class=\"portfolio-table-view__actions\">\n        <div class=\"portfolio-table-view__search-wrap\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" class=\"portfolio-table-view__search-icon\">\n            <circle cx=\"11\" cy=\"11\" r=\"8\" />\n            <line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\" />\n          </svg>\n          <input\n            v-model=\"searchQuery\"\n            type=\"search\"\n            class=\"iz-input portfolio-table-view__search\"\n            :placeholder=\"t('Search project...')\"\n            :aria-label=\"t('Search project')\"\n          />\n        </div>\n\n        <div class=\"portfolio-table-view__col-toggle\">\n          <button\n            type=\"button\"\n            class=\"iz-btn iz-btn--secondary portfolio-table-view__btn\"\n            :class=\"{ 'iz-btn--active': showColumnMenu }\"\n            @click=\"showColumnMenu = !showColumnMenu\"\n          >\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" /><path d=\"M9 3v18M15 3v18\" /></svg>\n            {{ t('Columns') }}\n          </button>\n          <div v-if=\"showColumnMenu\" class=\"portfolio-table-view__col-dropdown iz-card\">\n            <header><strong>{{ t('Visible columns') }}</strong></header>\n            <label v-for=\"col in columns\" :key=\"col.key\" class=\"portfolio-table-view__col-option\">\n              <input type=\"checkbox\" v-model=\"visibleColumns[col.key]\" :disabled=\"col.required\" />\n              <span>{{ col.label }}</span>\n            </label>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <section v-if=\"listedGaps.length\" class=\"iz-card portfolio-table-view__gap-list\" :aria-label=\"t('Planning gap intervals')\">\n      <h4>{{ t('{title} ({n})', { title: gapListTitle, n: listedGaps.length }) }}</h4>\n      <button v-for=\"gap in listedGaps\" :key=\"gap.id\" type=\"button\" class=\"iz-btn iz-btn--quiet iz-btn--sm\" @click=\"selectedGap = gap\">\n        {{ t('{type} · {name} · {start} – {end} ({duration})', { type: gap.type === 'internal' ? t('Initiation cards') : t('Between projects'), name: gap.name, start: gap.startDate, end: gap.endDate, duration: gap.duration }) }}\n      </button>\n    </section>\n    <PlanningGapDetails v-if=\"selectedGap\" :gap=\"selectedGap\" @close=\"closeGapDetails\" @open-project=\"openGapProject\" />\n    <details v-if=\"scheduleIssues.length\" class=\"iz-card portfolio-table-view__issues\">\n      <summary>{{ t('Schedule issues ({n})', { n: scheduleIssues.length }) }}</summary>\n      <p v-for=\"issue in scheduleIssues\" :key=\"issue.id\">{{ t('{project}: {note}', { project: issue.projectName, note: issue.note }) }}</p>\n    </details>\n    <details v-if=\"planningConflicts.length\" class=\"iz-card portfolio-table-view__issues\">\n      <summary>{{ t('Planning conflicts ({n})', { n: planningConflicts.length }) }}</summary>\n      <p v-for=\"conflict in planningConflicts\" :key=\"conflict.id\">{{ t('{project}: {note}', { project: conflict.projectName, note: conflict.note }) }}</p>\n    </details>\n\n    <!-- ── Table Section ── -->\n    <section class=\"iz-card portfolio-table-view__table-card\">\n      <header class=\"portfolio-table-view__table-header\">\n        <h4 class=\"iz-panel__title\">{{ t('Projects – Initiation Phase') }}</h4>\n        <span class=\"portfolio-table-view__badge\">{{ t('Table view') }}</span>\n      </header>\n\n      <div class=\"portfolio-table-view__table-container\">\n        <table class=\"portfolio-table\">\n          <thead>\n            <tr>\n              <th v-if=\"visibleColumns.project\" scope=\"col\" class=\"portfolio-table__th--sortable\" tabindex=\"0\" role=\"columnheader\" :aria-sort=\"ariaSort('name')\" @click=\"toggleSort('name')\" @keydown=\"onSortKeydown($event, 'name')\">\n                <span>{{ t('Project') }}</span>\n                <span class=\"portfolio-table__sort-arrow\" aria-hidden=\"true\">{{ sortArrow('name') }}</span>\n              </th>\n              <th v-if=\"visibleColumns.status\" scope=\"col\">{{ t('Process status') }}</th>\n              <th v-if=\"visibleColumns.completion\" scope=\"col\" class=\"portfolio-table__th--sortable\" tabindex=\"0\" role=\"columnheader\" :aria-sort=\"ariaSort('completionPct')\" @click=\"toggleSort('completionPct')\" @keydown=\"onSortKeydown($event, 'completionPct')\">\n                <span>{{ t('% done') }}</span>\n                <span class=\"portfolio-table__sort-arrow\" aria-hidden=\"true\">{{ sortArrow('completionPct') }}</span>\n              </th>\n              <th v-if=\"visibleColumns.expected\" scope=\"col\">{{ t('Expected / reached 100%') }}</th>\n              <th v-if=\"visibleColumns.startPrep\" scope=\"col\">{{ t('Start Work Preparation') }}</th>\n              <th v-if=\"visibleColumns.countdownPrep\" scope=\"col\">{{ t('Countdown to start Work Preparation') }}</th>\n              <th v-if=\"visibleColumns.minExec\" scope=\"col\">{{ t('Min. execution start') }}</th>\n              <th v-if=\"visibleColumns.wensweek\" scope=\"col\" class=\"portfolio-table__th--sortable\" tabindex=\"0\" role=\"columnheader\" :aria-sort=\"ariaSort('desiredStartDate')\" @click=\"toggleSort('desiredStartDate')\" @keydown=\"onSortKeydown($event, 'desiredStartDate')\">\n                <span>{{ t('Desired week') }}</span>\n                <span class=\"portfolio-table__sort-arrow\" aria-hidden=\"true\">{{ sortArrow('desiredStartDate') }}</span>\n              </th>\n              <th v-if=\"visibleColumns.countdownWensweek\" scope=\"col\">{{ t('Countdown to Desired Week') }}</th>\n              <th v-if=\"visibleColumns.actualStart\" scope=\"col\" class=\"portfolio-table__th--sortable\" tabindex=\"0\" role=\"columnheader\" :aria-sort=\"ariaSort('actualStartDate')\" @click=\"toggleSort('actualStartDate')\" @keydown=\"onSortKeydown($event, 'actualStartDate')\">\n                <span>{{ t('Actual start week') }}</span>\n                <span class=\"portfolio-table__sort-arrow\" aria-hidden=\"true\">{{ sortArrow('actualStartDate') }}</span>\n              </th>\n              <th v-if=\"visibleColumns.cards\" scope=\"col\">{{ t('Open cards') }}</th>\n              <th v-if=\"visibleColumns.gap\" scope=\"col\">{{ t('Planning gap') }}</th>\n              <th scope=\"col\" class=\"portfolio-table__th--action\"><span class=\"sr-only\">{{ t('Action') }}</span></th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr v-if=\"loading\">\n              <td colspan=\"13\" class=\"portfolio-table__empty\">{{ t('Loading data...') }}</td>\n            </tr>\n            <tr v-else-if=\"paginatedProjects.length === 0\">\n              <td colspan=\"13\" class=\"portfolio-table__empty\">{{ t('No projects found for selected filters.') }}</td>\n            </tr>\n            <tr\n              v-else\n              v-for=\"project in paginatedProjects\"\n              :key=\"project.id\"\n              class=\"portfolio-table__row\"\n              tabindex=\"0\"\n              :aria-label=\"t('Open details for {name}', { name: project.name })\"\n              @click=\"onRowClick(project)\"\n              @keydown=\"onRowKeydown($event, project)\"\n            >\n              <!-- 1. Project Name -->\n              <td v-if=\"visibleColumns.project\" class=\"portfolio-table__cell-project\">\n                <strong>{{ project.name }}</strong>\n              </td>\n\n              <!-- 2. Process Status Badge -->\n              <td v-if=\"visibleColumns.status\">\n                <span class=\"iz-badge\" :class=\"statusBadgeClass(project.bucket)\">\n                  {{ bucketLabel(project.bucket) || project.bucketLabel }}\n                </span>\n              </td>\n\n              <!-- 3. % Done -->\n              <td v-if=\"visibleColumns.completion\">\n                <span class=\"portfolio-table__pct-pill\" :class=\"{ 'portfolio-table__pct-pill--done': project.completionPct === 100 }\">\n                  {{ t('{pct}%', { pct: project.completionPct }) }}\n                </span>\n              </td>\n\n              <!-- 4. Expected / Reached 100% -->\n              <td v-if=\"visibleColumns.expected\">\n                <span :class=\"{ 'portfolio-table__text--success': project.isCompleted }\">\n                  {{ project.expectedOrAchievedLabel }}\n                </span>\n              </td>\n\n              <!-- 5. Start Work Preparation -->\n              <td v-if=\"visibleColumns.startPrep\">\n                <span>{{ project.startPrepWeek }}</span>\n              </td>\n\n              <!-- 6. Countdown to Start Work Preparation -->\n              <td v-if=\"visibleColumns.countdownPrep\">\n                <span>{{ project.startPrepCountdown }}</span>\n              </td>\n\n              <!-- 7. Min. Execution Start -->\n              <td v-if=\"visibleColumns.minExec\">\n                <span>{{ project.minExecutionStartWeek }}</span>\n              </td>\n\n              <!-- 8. Desired Week -->\n              <td v-if=\"visibleColumns.wensweek\" class=\"portfolio-table__cell-wensweek\">\n                <strong>{{ project.desiredStartWeek }}</strong>\n                <small v-if=\"project.isLeadingDesiredWeek\" class=\"portfolio-table__leading-note\">{{ t('actual desired week is leading') }}</small>\n              </td>\n\n              <!-- 9. Countdown to Desired Week -->\n              <td v-if=\"visibleColumns.countdownWensweek\">\n                <span>{{ project.desiredCountdown }}</span>\n              </td>\n\n              <!-- 10. Actual Start Week -->\n              <td v-if=\"visibleColumns.actualStart\">\n                <span>{{ project.actualStartWeek || \"—\" }}</span>\n              </td>\n\n              <!-- 10. Open Cards -->\n              <td v-if=\"visibleColumns.cards\">\n                <button\n                  type=\"button\"\n                  class=\"portfolio-table__cards-btn\"\n                  :title=\"t('Open Deck board')\"\n                  @click.stop=\"openDeckBoard(project)\"\n                >\n                  <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" class=\"portfolio-table__deck-icon\">\n                    <rect x=\"3\" y=\"3\" width=\"7\" height=\"9\" />\n                    <rect x=\"14\" y=\"3\" width=\"7\" height=\"5\" />\n                    <rect x=\"14\" y=\"12\" width=\"7\" height=\"9\" />\n                    <rect x=\"3\" y=\"16\" width=\"7\" height=\"5\" />\n                  </svg>\n                  <span>{{ project.openCards }}</span>\n                  <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" class=\"portfolio-table__arrow-icon\">\n                    <polyline points=\"9 18 15 12 9 6\" />\n                  </svg>\n                </button>\n              </td>\n\n              <!-- 11. Planning Gap -->\n              <td v-if=\"visibleColumns.gap\">\n                <button v-if=\"project.planningGap.hasGap\" type=\"button\" class=\"iz-badge iz-badge--danger portfolio-table-view__gap-button\" @click.stop=\"openProjectGap(project)\">\n                  {{ project.planningGap.display }}\n                </button>\n                <span v-else class=\"iz-badge iz-badge--success\">{{ t('None') }}</span>\n              </td>\n\n              <!-- 12. Row Action Chevron -->\n              <td class=\"portfolio-table__cell-arrow\">\n                <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" class=\"portfolio-table__row-arrow\">\n                  <polyline points=\"9 18 15 12 9 6\" />\n                </svg>\n              </td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n\n      <!-- ── Table Footer & Pagination ── -->\n      <footer class=\"portfolio-table-view__table-footer\">\n        <span class=\"portfolio-table-view__hint\">\n          {{ t('Click a project (or press Enter on a focused row) to open its details in Project Performance Analytics below.') }}\n        </span>\n\n        <div class=\"portfolio-table-view__pagination\" role=\"navigation\" :aria-label=\"t('Table pages')\">\n          <button\n            type=\"button\"\n            class=\"portfolio-table-view__page-btn\"\n            :disabled=\"currentPage <= 1\"\n            :aria-label=\"t('Previous page')\"\n            @click=\"currentPage--\"\n          >\n            ‹\n          </button>\n          <button\n            v-for=\"p in totalPages\"\n            :key=\"p\"\n            type=\"button\"\n            class=\"portfolio-table-view__page-btn\"\n            :class=\"{ 'portfolio-table-view__page-btn--active': currentPage === p }\"\n            :aria-label=\"t('Page {n}', { n: p })\"\n            :aria-current=\"currentPage === p ? 'page' : null\"\n            @click=\"currentPage = p\"\n          >\n            {{ p }}\n          </button>\n          <button\n            type=\"button\"\n            class=\"portfolio-table-view__page-btn\"\n            :disabled=\"currentPage >= totalPages\"\n            :aria-label=\"t('Next page')\"\n            @click=\"currentPage++\"\n          >\n            ›\n          </button>\n          <span class=\"portfolio-table-view__page-info\">\n            {{ pageCountDisplay }}\n          </span>\n        </div>\n      </footer>\n    </section>\n\n    <!-- ── Brand Footer ── -->\n    <footer class=\"portfolio-table-view__brand-footer\">\n      <span class=\"portfolio-table-view__brand\">\n        <strong>{{ t('InZicht') }}</strong> {{ t('Together making projects insightful.') }}\n      </span>\n      <span class=\"portfolio-table-view__brand-sync\">\n        {{ t('All data is live and current for the selected filters.') }}\n      </span>\n    </footer>\n  </div>\n</template>\n\n<script>\nimport axios from \"@nextcloud/axios\";\nimport { generateUrl } from \"@nextcloud/router\";\nimport PlanningGapDetails from \"./PlanningGapDetails.vue\";\nimport PeopleLoadGrid from \"./PeopleLoadGrid.vue\";\nimport { t, n, locale } from \"../lib/l10n.mjs\";\n\n// Progression filters by projectcreatoraio's bucket key. Its labels are\n// English data, so the words are chosen here; the key drives the filter.\nfunction bucketLabelOf(key) {\n  switch (key) {\n    case \"all\": return t(\"All progression\");\n    case \"0-24\": return t(\"0–24%\");\n    case \"25-49\": return t(\"25–49%\");\n    case \"50-74\": return t(\"50–74%\");\n    case \"75-99\": return t(\"75–99% / Upcoming\");\n    case \"100\": return t(\"100% ready for handover\");\n    case \"gaps\": return t(\"Projects with gaps\");\n    case \"in-period\": return t(\"In selected period\");\n    default: return \"\";\n  }\n}\n\nexport default {\n  name: \"ProjectPortfolioTableView\",\n  components: { PlanningGapDetails, PeopleLoadGrid },\n  props: {\n    organizationId: { type: Number, default: null },\n    initialFilter: { type: String, default: \"all\" },\n    weekStart: { type: String, default: null },\n    scope: { type: String, default: \"mine\" },\n    teamId: { type: Number, default: null },\n    teams: { type: Array, default: function () { return []; } },\n  },\n  data: function () {\n    return {\n      tableData: null,\n      selectedGap: null,\n      gapFocusProject: null,\n      loading: false,\n      error: null,\n      tableRequestId: 0,\n      activeFilter: this.initialFilter || \"all\",\n      searchQuery: \"\",\n      currentPage: 1,\n      pageSize: 10,\n      sortKey: \"name\",\n      sortAsc: true,\n      showColumnMenu: false,\n      lastUpdated: new Date(),\n      visibleColumns: {\n        project: true,\n        status: true,\n        completion: true,\n        expected: true,\n        startPrep: true,\n        countdownPrep: true,\n        minExec: true,\n        wensweek: true,\n        countdownWensweek: true,\n        actualStart: true,\n        cards: true,\n        gap: true,\n      },\n      columns: [\n        { key: \"project\", label: t(\"Project\"), required: true },\n        { key: \"status\", label: t(\"Process status\") },\n        { key: \"completion\", label: t(\"% done\") },\n        { key: \"expected\", label: t(\"Expected / reached 100%\") },\n        { key: \"startPrep\", label: t(\"Start Work Preparation\") },\n        { key: \"countdownPrep\", label: t(\"Countdown to start Work Preparation\") },\n        { key: \"minExec\", label: t(\"Min. execution start\") },\n        { key: \"wensweek\", label: t(\"Desired week\") },\n        { key: \"countdownWensweek\", label: t(\"Countdown to Desired Week\") },\n        { key: \"actualStart\", label: t(\"Actual start week\") },\n        { key: \"cards\", label: t(\"Open cards\") },\n        { key: \"gap\", label: t(\"Planning gap\") },\n      ],\n    };\n  },\n  computed: {\n    lastUpdatedText: function () {\n      if (!this.lastUpdated) return t(\"today\");\n      var time = this.lastUpdated.toLocaleTimeString(locale(), { hour: \"2-digit\", minute: \"2-digit\" });\n      return t(\"today {time}\", { time: time });\n    },\n    maxPerPerson: function () {\n      return (this.tableData && this.tableData.maxProjectsPerMember) || 2;\n    },\n    scopeKey: function () {\n      return this.scope === \"team\" ? \"team:\" + this.teamId : this.scope;\n    },\n    teamSummaryText: function () {\n      if (!this.tableData || !this.tableData.scope) return \"\";\n      var scope = this.tableData.scope;\n      var limit = t(\"max {n} projects per person\", { n: this.maxPerPerson });\n      var teamCount = (this.tableData.teams || []).length;\n      if (scope.type === \"mine\") {\n        return n(\"My load across %n team, {limit}\", \"My load across %n teams, {limit}\", teamCount, { limit: limit });\n      }\n      if (scope.type === \"team\" && scope.team) {\n        return t(\"{people}, {limit}\", { people: this.peopleCount(scope.team.memberCount), limit: limit });\n      }\n      return n(\"{people} in %n team, {limit}\", \"{people} in %n teams, {limit}\", teamCount, { people: this.peopleCount((this.tableData.people || []).length), limit: limit });\n    },\n    periodStart: function () {\n      if (this.tableData && this.tableData.period && this.tableData.period.weekStart) {\n        return this.tableData.period.weekStart;\n      }\n      return this.weekStart || \"\";\n    },\n    periodEnd: function () {\n      if (this.tableData && this.tableData.period && this.tableData.period.weekEnd) {\n        return this.tableData.period.weekEnd;\n      }\n      if (this.periodStart) {\n        var start = this.parseDate(this.periodStart);\n        start.setUTCDate(start.getUTCDate() + 41);\n        return start.toISOString().slice(0, 10);\n      }\n      return \"\";\n    },\n    currentWeekStart: function () {\n      return this.periodStart || \"\";\n    },\n    inPeriodCount: function () {\n      var list = (this.tableData && this.tableData.projects) || [];\n      var pStart = this.periodStart;\n      var pEnd = this.periodEnd;\n      if (!pStart || !pEnd) return 0;\n      var self = this;\n      return list.filter(function (p) {\n        return self.isProjectInPeriod(p, pStart, pEnd);\n      }).length;\n    },\n    periodLabel: function () {\n      if (!this.tableData || !this.tableData.period) return t(\"Period not available\");\n      var start = this.parseDate(this.tableData.period.weekStart);\n      var end = new Date(start.getTime());\n      end.setUTCDate(end.getUTCDate() + 41);\n      return t(\"{start} – {end} (6 weeks)\", { start: this.isoYearWeek(start), end: this.isoYearWeek(end) });\n    },\n    periodWeekRange: function () {\n      if (!this.tableData || !this.tableData.period) return t(\"Period not available\");\n      var start = this.parseDate(this.tableData.period.weekStart);\n      var end = new Date(start.getTime());\n      end.setUTCDate(end.getUTCDate() + 41);\n      return this.isoYearWeek(start) + \"-\" + this.isoYearWeek(end);\n    },\n    weeks: function () {\n      return (this.tableData && this.tableData.weeks) || [];\n    },\n    planningGaps: function () { return (this.tableData && this.tableData.planningGaps) || []; },\n    scheduleIssues: function () { return (this.tableData && this.tableData.scheduleIssues) || []; },\n    planningConflicts: function () { return (this.tableData && this.tableData.planningConflicts) || []; },\n    listedGaps: function () {\n      if (this.gapFocusProject) {\n        var ids = this.gapFocusProject.planningGap.gapIds || [];\n        return this.planningGaps.filter(function (gap) { return ids.indexOf(gap.id) !== -1; });\n      }\n      return this.activeFilter === \"gaps\" ? this.planningGaps : [];\n    },\n    gapListTitle: function () {\n      return this.gapFocusProject ? t(\"Planning gaps · {name}\", { name: this.gapFocusProject.name }) : t(\"Open planning gaps\");\n    },\n    filterChips: function () {\n      var rawBuckets = (this.tableData && this.tableData.buckets) ? this.tableData.buckets.slice() : [\n        { key: \"all\", count: 0 },\n        { key: \"0-24\", count: 0 },\n        { key: \"25-49\", count: 0 },\n        { key: \"50-74\", count: 0 },\n        { key: \"75-99\", count: 0 },\n        { key: \"100\", count: 0 },\n        { key: \"gaps\", count: 0 },\n      ];\n      // The label comes from the key; the backend's own label is only a\n      // fallback for a key this view does not know.\n      var buckets = rawBuckets.map(function (b) {\n        return Object.assign({}, b, { label: bucketLabelOf(b.key) || b.label || \"\" });\n      });\n      buckets.push({\n        key: \"in-period\",\n        label: bucketLabelOf(\"in-period\"),\n        count: this.inPeriodCount,\n      });\n      return buckets;\n    },\n    filteredProjects: function () {\n      var list = (this.tableData && this.tableData.projects) || [];\n      var filter = this.activeFilter;\n      var q = (this.searchQuery || \"\").trim().toLowerCase();\n      var pStart = this.periodStart;\n      var pEnd = this.periodEnd;\n      var self = this;\n\n      return list.filter(function (p) {\n        // Status or in-period chip filter\n        if (filter === \"in-period\") {\n          if (!self.isProjectInPeriod(p, pStart, pEnd)) return false;\n        } else if (filter === \"gaps\") {\n          if (!p.planningGap || !p.planningGap.hasGap) return false;\n        } else if (filter !== \"all\") {\n          if (p.bucket !== filter) return false;\n        }\n\n        // Substring search\n        if (q) {\n          var name = (p.name || \"\").toLowerCase();\n          if (name.indexOf(q) === -1) return false;\n        }\n\n        return true;\n      });\n    },\n    sortedProjects: function () {\n      var list = this.filteredProjects.slice();\n      var key = this.sortKey;\n      var asc = this.sortAsc ? 1 : -1;\n\n      return list.sort(function (a, b) {\n        var valA = a[key] ?? \"\";\n        var valB = b[key] ?? \"\";\n        if (typeof valA === \"string\") valA = valA.toLowerCase();\n        if (typeof valB === \"string\") valB = valB.toLowerCase();\n        if (valA < valB) return -1 * asc;\n        if (valA > valB) return 1 * asc;\n        return 0;\n      });\n    },\n    totalPages: function () {\n      return Math.max(1, Math.ceil(this.sortedProjects.length / this.pageSize));\n    },\n    paginatedProjects: function () {\n      var start = (this.currentPage - 1) * this.pageSize;\n      return this.sortedProjects.slice(start, start + this.pageSize);\n    },\n    pageCountDisplay: function () {\n      var count = this.paginatedProjects.length;\n      var total = this.sortedProjects.length;\n      return t(\"{count} / {total}\", { count: count, total: total });\n    },\n  },\n  watch: {\n    weekStart: function () {\n      this.currentPage = 1;\n      this.fetchTableData();\n    },\n    scopeKey: function () {\n      this.currentPage = 1;\n      this.fetchTableData();\n    },\n    initialFilter: function (val) {\n      if (val) this.activeFilter = val;\n    },\n    activeFilter: function () {\n      this.currentPage = 1;\n      this.gapFocusProject = null;\n    },\n    searchQuery: function () {\n      this.currentPage = 1;\n    },\n    sortKey: function () {\n      this.currentPage = 1;\n    },\n    tableData: function () {\n      this.selectedGap = null;\n      this.gapFocusProject = null;\n      this.clampPage();\n    },\n    sortedProjects: function () {\n      this.clampPage();\n    },\n  },\n  mounted: function () {\n    this.fetchTableData();\n  },\n  methods: {\n    openProjectGap: function (project) {\n      // Several gaps: list them all so each can be opened, not only the first.\n      this.gapFocusProject = (project.planningGap.gapIds || []).length > 1 ? project : null;\n      var ids = project.planningGap.gapIds || [];\n      this.selectedGap = this.planningGaps.find(function (gap) { return ids.indexOf(gap.id) !== -1; }) || null;\n    },\n    closeGapDetails: function () {\n      this.selectedGap = null;\n      this.gapFocusProject = null;\n    },\n    openGapProject: function (project) {\n      // The detail view needs the full table row; gap anchors carry only id and name.\n      var rows = (this.tableData && this.tableData.projects) || [];\n      var row = rows.find(function (p) { return 